// Pega todos os itens que vieram do nó 'AI Agent' ou 'AI revision agent'
const inputItems = $input.all();

// Pega a lista original de tickets do nó 'Get_ticket' para garantir a correspondência
const originalTickets = $items("Get_ticket");

const results = [];

// Itera sobre cada item que chegou neste nó (seja do AI Agent ou do AI revision agent)
for (let i = 0; i < inputItems.length; i++) {
  const currentItem = inputItems[i].json;

  // Encontra o ticket original correspondente pelo índice.
  // Isso garante que estamos associando a resposta ao ticket certo.
  const originalTicketData = originalTickets[i] ? originalTickets[i].json : {};

  // A resposta da IA estará no campo 'output' do item atual.
  // Não precisamos mais checar de qual agente veio, pois o loop já nos isolou.
  const finalResponse = currentItem.output || "Nenhuma resposta válida foi gerada.";

  // Monta o objeto final, combinando os dados do ticket original com a nova resposta.
  const finalItem = {
    ...originalTicketData,
    final_response: finalResponse
  };

  results.push({ json: finalItem });
}

// Retorna uma lista de itens, um para cada ticket processado.
return results;

try {
  // 1. CAPTURA DOS DADOS
  const aiResponse = $('Code').first().json.final_response;
  const ticketData = $('Get_ticket').first().json;

  // 2. FUNÇÃO DE CONVERSÃO SIMPLIFICADA
  function convertToHTML(text) {
    if (typeof text !== 'string') {
      text = String(text);
    }

    // Converte quebras de linha duplas em parágrafos
    let paragraphs = text.split('\n\n');
    let html = paragraphs.map(p => {
      if (p.trim()) {
        // Converte URLs em links clicáveis
        p = p.replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank">$1</a>');
        // Converte quebras de linha simples em <br>
        p = p.replace(/\n/g, '<br>');
        return `<p>${p}</p>`;
      }
      return '';
    }).filter(p => p).join('\n');

    return html;
  }

  // 3. GERA O HTML
  const htmlContent = convertToHTML(aiResponse);

  // 4. TEMPLATE HTML PARA FRESHDESK
  const htmlBody = `<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
${htmlContent}
<br><br>
<p>Atenciosamente,<br>
<strong>Equipe Brokers</strong><br>
EEmovel Brokers<br>
suporte@eemovel.com.br</p>
</div>`;

  // 5. RETORNA O JSON NO FORMATO FRESHDESK
  return {
    json: {
      body: htmlBody,
      ticketId: ticketData.id,
      requesterEmail: ticketData.requester ? ticketData.requester.email : ticketData.email
    }
  };

} catch (error) {
  throw new Error(`Erro ao processar resposta: ${error.message}`);
}

